// tokenServe spins a Service over a hand-published artifact (one dummy build
// with a head playlist and a tail segment under t/, plus one original file)
// behind an httptest server. Returns the service, the server, the playlist
// bytes, and the tail segment's bytes.
func tokenServe(t *testing.T) (*Service, *httptest.Server, []byte, []byte) {
	t.Helper()
	dir := t.TempDir()
	root := filepath.Join(dir, "streams")
	playlist := []byte("#EXTM3U\n#EXT-X-ENDLIST\n")
	build := filepath.Join(root, "it_tok", "nonce01")
	if err := os.MkdirAll(filepath.Join(build, "t"), 0o755); err != nil {
		t.Fatalf("mkdir build: %v", err)
	}
	if err := os.WriteFile(filepath.Join(build, "index.m3u8"), playlist, 0o644); err != nil {
		t.Fatalf("write playlist: %v", err)
	}
	tail := []byte("tail-segment-payload")
	if err := os.WriteFile(filepath.Join(build, "t", "seg-00007.m4s"), tail, 0o644); err != nil {
		t.Fatalf("write tail segment: %v", err)
	}
	original := filepath.Join(dir, "original.mkv")
	if err := os.WriteFile(original, []byte("0123456789abcdef"), 0o644); err != nil {
		t.Fatalf("write original: %v", err)
	}
	s := newTestService(t, root, time.Second)
	s.Original = func(context.Context, string) (string, bool) { return original, true }
	srv := httptest.NewServer(s)
	t.Cleanup(srv.Close)
	return s, srv, playlist, tail
}

// get issues one request against the test server.
func get(t *testing.T, srv *httptest.Server, path string, header http.Header) *http.Response {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, srv.URL+path, nil)
	if err != nil {
		t.Fatalf("new request: %v", err)
	}
	req.Header = header
	resp, err := srv.Client().Do(req)
	if err != nil {
		t.Fatalf("GET %s: %v", path, err)
	}
	t.Cleanup(func() { resp.Body.Close() })
	return resp
}

// TestMediaToken is the spec floor for "Media tokens + /media surface" (probe
// bd3cab860208a495): cookie-primary with query fallback, 4 h TTL, the item the
// token names is the only one it serves, the admin credential is not accepted,
// and no token value is ever logged.
func TestMediaToken(t *testing.T) {
	s, srv, playlist, _ := tokenServe(t)
	token, _ := s.Issue("it_tok", timeNow())

	t.Run("cookie_serves_the_artifact", func(t *testing.T) {
		resp := get(t, srv, "/media/it_tok/nonce01/index.m3u8", http.Header{"Cookie": {"media_token=" + token}})
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		if ct := resp.Header.Get("Content-Type"); ct != "application/vnd.apple.mpegurl" {
			t.Fatalf("content type = %q, want the playlist media type", ct)
		}
		body := readBody(t, resp)
		if !bytes.Equal(body, playlist) {
			t.Fatalf("body = %q, want the published bytes", body)
		}
	})

	t.Run("query_fallback_serves_the_same_bytes", func(t *testing.T) {
		resp := get(t, srv, "/media/it_tok/nonce01/index.m3u8?token="+token, nil)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		if !bytes.Equal(readBody(t, resp), playlist) {
			t.Fatal("query-token body differs from the cookie-token body")
		}
	})

	t.Run("rejections", func(t *testing.T) {
		cases := []struct {
			name, path string
			header     http.Header
		}{
			{"no_token", "/media/it_tok/nonce01/index.m3u8", nil},
			{"wrong_secret", "/media/it_tok/nonce01/index.m3u8?token=" + mustForeignToken(t), nil},
			{"token_for_other_item", "/media/it_tok/nonce01/index.m3u8?token=" + mustOtherItemToken(t, s), nil},
			{"expired_token", "/media/it_tok/nonce01/index.m3u8?token=" + mustExpiredToken(t, s), nil},
			{"admin_bearer_rejected", "/media/it_tok/nonce01/index.m3u8", http.Header{"Authorization": {"Bearer admin-secret"}}},
			{"traversal_rejected", "/media/..%2F..%2Fetc%2Fpasswd/x/index.m3u8?token=" + token, nil},
			{"non_artifact_ext", "/media/it_tok/nonce01/secret.txt?token=" + token, nil},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				if resp := get(t, srv, tc.path, tc.header); resp.StatusCode != http.StatusUnauthorized && resp.StatusCode != http.StatusNotFound {
					t.Fatalf("status = %d, want 401/404", resp.StatusCode)
				}
			})
		}
	})

	t.Run("post_not_allowed", func(t *testing.T) {
		req, _ := http.NewRequest(http.MethodPost, srv.URL+"/media/it_tok/nonce01/index.m3u8?token="+token, nil)
		resp, err := srv.Client().Do(req)
		if err != nil {
			t.Fatalf("POST: %v", err)
		}
		resp.Body.Close()
		if resp.StatusCode != http.StatusMethodNotAllowed {
			t.Fatalf("status = %d, want 405", resp.StatusCode)
		}
	})

	t.Run("original_serves_with_range", func(t *testing.T) {
		resp := get(t, srv, "/media/it_tok/original?token="+token, http.Header{"Range": {"bytes=0-9"}})
		if resp.StatusCode != http.StatusPartialContent {
			t.Fatalf("status = %d, want 206", resp.StatusCode)
		}
		if body := string(readBody(t, resp)); body != "0123456789" {
			t.Fatalf("range body = %q, want the first 10 bytes", body)
		}
	})

	t.Run("expired_clock_rejects", func(t *testing.T) {
		base := timeNow()
		overrideTimeNow(t, func() time.Time { return base.Add(5 * time.Hour) }) // past the 4h TTL
		if resp := get(t, srv, "/media/it_tok/nonce01/index.m3u8?token="+token, nil); resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("status = %d, want 401 past TTL", resp.StatusCode)
		}
	})

	t.Run("tokens_never_logged", func(t *testing.T) {
		buf := &logBuffer{}
		prev := slog.Default()
		slog.SetDefault(slog.New(buf))
		defer slog.SetDefault(prev)
		// Both a served request and a rejected one: neither may leak the token.
		get(t, srv, "/media/it_tok/nonce01/index.m3u8?token="+token, nil)
		get(t, srv, "/media/it_tok/nonce01/index.m3u8", nil)
		if strings.Contains(buf.String(), token) {
			t.Fatal("a media token value reached the log")
		}
	})
}

// TestSections is the spec floor for the descriptor's sections projection (the
// sections half of box 2.5's Interface): stored ffprobe chapters project to
// {kind:"chapter", start, end?, title?} ordered by start — and the marker kind
// is never produced in v1.
func TestSections(t *testing.T) {
	s := &Service{Secret: []byte("k")}
	doc := func(ffprobe map[string]any) map[string]any {
		return map[string]any{"ffprobe": ffprobe}
	}

	t.Run("chapters_project_sorted", func(t *testing.T) {
		// The PRIMARY shape is real ffprobe output: titles nested under
		// tags.title (`ffprobe -show_chapters` never emits a top-level
		// chapter title — the tags carry it).
		_, _, _, sections, _ := s.Describe("it", doc(map[string]any{
			"chapters": []any{
				map[string]any{"start_time": "5.5", "end_time": "9.25", "tags": map[string]any{"title": "middle"}},
				map[string]any{"start_time": "0", "end_time": "5.5", "tags": map[string]any{"title": "intro"}},
				map[string]any{"start_time": "9.25", "end_time": "12", "tags": map[string]any{"title": "outro"}},
			},
		}))
		if len(sections) != 3 {
			t.Fatalf("sections = %v, want 3", sections)
		}
		if got := sections[0]["start"].(float64); got != 0 {
			t.Fatalf("first section start = %v, want sorted-by-start (0)", got)
		}
		for i, sec := range sections {
			if sec["kind"] != SectionKindChapter {
				t.Fatalf("section %d kind = %v, want %q (marker must never be produced in v1)", i, sec["kind"], SectionKindChapter)
			}
		}
		if sections[2]["end"] != 12.0 || sections[2]["title"] != "outro" {
			t.Fatalf("last section = %v, want end 12 + tags.title outro", sections[2])
		}
	})

	t.Run("top_level_title_fallback", func(t *testing.T) {
		// Secondary shape: a top-level chapter title (no tags) still carries
		// through — the projection accepts both.
		_, _, _, sections, _ := s.Describe("it", doc(map[string]any{
			"chapters": []any{
				map[string]any{"start_time": "1", "end_time": "2", "title": "top-level"},
				map[string]any{"start_time": "2", "end_time": "3", "tags": map[string]any{"not_a_title": "x"}},
			},
		}))
		if len(sections) != 2 {
			t.Fatalf("sections = %v, want 2", sections)
		}
		if sections[0]["title"] != "top-level" {
			t.Fatalf("first section title = %v, want the top-level fallback carried through", sections[0]["title"])
		}
		if _, ok := sections[1]["title"]; ok {
			t.Fatalf("second section = %v, want untitled when tags carry no title", sections[1])
		}
	})

	t.Run("raw_time_base_fallback", func(t *testing.T) {
		_, _, _, sections, _ := s.Describe("it", doc(map[string]any{
			"chapters": []any{map[string]any{"start": 1500.0, "time_base": "1/1000", "title": "raw"}},
		}))
		if len(sections) != 1 || sections[0]["start"] != 1.5 {
			t.Fatalf("sections = %v, want start 1.5 from 1500 @ 1/1000", sections)
		}
	})

	t.Run("unusable_chapter_dropped_and_absent_probe_nil", func(t *testing.T) {
		if _, _, _, got, _ := s.Describe("it", doc(map[string]any{
			"chapters": []any{map[string]any{"title": "no boundaries"}},
		})); len(got) != 0 {
			t.Fatalf("sections = %v, want the boundary-less chapter dropped", got)
		}
		if _, _, _, got, _ := s.Describe("it", map[string]any{}); got != nil {
			t.Fatalf("sections = %v, want nil without ffprobe", got)
		}
	})

	t.Run("mode_and_play_url_follow_the_stored_state", func(t *testing.T) {
		s.Root = t.TempDir() // the complete-build guard stats the build on disk
		cases := []struct {
			name, streamsState, playlist, nonce, wantMode string
		}{
			{"no_packaging", "", "", "", ModeDirect},
			{"failed_pack", StateFailed, "/media/it/bad/index.m3u8", "", ModeDirect},
			{"partial_build", StatePartial, "/media/it/n1/index.m3u8", "", ModeHls},
			{"complete_build", StateComplete, "/media/it/n1/index.m3u8", "n1", ModeHls},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				d := map[string]any{}
				if tc.streamsState != "" {
					ns := map[string]any{"state": tc.streamsState, "playlist": tc.playlist}
					if tc.nonce != "" {
						// A complete doc must point at a real, healthy build or
						// the integrity guard (D5) answers the direct floor.
						ns["nonce"] = tc.nonce
						handBuild(t, s.Root, "it", tc.nonce, healthyPlaylist,
							"init.mp4", "seg-00000.m4s", "seg-00001.m4s")
					}
					d["streams"] = ns
				}
				mode, state, playURL, _, _ := s.Describe("it", d)
				if mode != tc.wantMode {
					t.Fatalf("mode = %q, want %q", mode, tc.wantMode)
				}
				wantState := tc.streamsState
				if wantState == "" {
					wantState = StateNone
				}
				if state != wantState {
					t.Fatalf("state = %q, want %q", state, wantState)
				}
				wantPrefix := tc.playlist
				if tc.wantMode == ModeDirect {
					wantPrefix = "/media/it/original"
				}
				if !strings.HasPrefix(playURL, wantPrefix+"?token=") {
					t.Fatalf("playURL = %q, want %q?token=<minted>", playURL, wantPrefix)
				}
				// The minted play token verifies for the item (the descriptor
				// hands the client a usable playback grant).
				tok := strings.TrimPrefix(playURL, wantPrefix+"?token=")
				if granted, err := s.verify(tok, timeNow()); err != nil || granted != "it" {
					t.Fatalf("play URL token does not verify for the item: granted=%q err=%v", granted, err)
				}
			})
		}
	})
}

// TestTailSegmentServe is the spec floor for tail-phase serving (INV3 + the
// serveArtifact contract): a tail segment published under <nonce>/t/ serves
// byte-identical through the /media surface; every path component is
// validated, so a dot-dot component is 404 — and without a token the
// segment is unreachable like any other artifact.
func TestTailSegmentServe(t *testing.T) {
	s, srv, _, tail := tokenServe(t)
	token, _ := s.Issue("it_tok", timeNow())

	t.Run("tail_segment_serves_byte_identical", func(t *testing.T) {
		resp := get(t, srv, "/media/it_tok/nonce01/t/seg-00007.m4s?token="+token, nil)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		if ct := resp.Header.Get("Content-Type"); ct != "video/iso.segment" {
			t.Fatalf("content type = %q, want the segment media type", ct)
		}
		if body := readBody(t, resp); !bytes.Equal(body, tail) {
			t.Fatalf("body = %q, want the published tail bytes", body)
		}
	})

	t.Run("no_token_rejected", func(t *testing.T) {
		if resp := get(t, srv, "/media/it_tok/nonce01/t/seg-00007.m4s", nil); resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("status = %d, want 401", resp.StatusCode)
		}
	})

	t.Run("traversal_rejected", func(t *testing.T) {
		// A dot-dot climb out of the nonce directory (same item, so the
		// token still grants) must land on nothing servable — 404, never a
		// byte from outside the published build.
		resp := get(t, srv, "/media/it_tok/nonce01/t/..%2F..%2Felsewhere%2Fseg-00007.m4s?token="+token, nil)
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want 404", resp.StatusCode)
		}
	})
}

// TestDirectFloor is the spec floor for the direct playback floor (probe
// 54f84d49b11d57df): the original bytes serve through /media/<id>/original
// with stdlib Range handling and zero transform — and no media process is
// involved: the fixture's ffmpeg pointer names a binary that cannot run, so
// a byte-identical response proves serving never reached the pack lane's
// exec site.
func TestDirectFloor(t *testing.T) {
	s, srv, _, _ := tokenServe(t)
	s.FFmpeg = "definitely-not-a-real-ffmpeg-binary"
	token, _ := s.Issue("it_tok", timeNow())
	const original = "0123456789abcdef"

	t.Run("range_serves_partial_content", func(t *testing.T) {
		resp := get(t, srv, "/media/it_tok/original?token="+token, http.Header{"Range": {"bytes=0-9"}})
		if resp.StatusCode != http.StatusPartialContent {
			t.Fatalf("status = %d, want 206", resp.StatusCode)
		}
		if body := string(readBody(t, resp)); body != original[:10] {
			t.Fatalf("range body = %q, want the first 10 bytes", body)
		}
	})

	t.Run("suffix_range_serves_the_tail", func(t *testing.T) {
		resp := get(t, srv, "/media/it_tok/original?token="+token, http.Header{"Range": {"bytes=12-"}})
		if resp.StatusCode != http.StatusPartialContent {
			t.Fatalf("status = %d, want 206", resp.StatusCode)
		}
		if body := string(readBody(t, resp)); body != original[12:] {
			t.Fatalf("range body = %q, want the last 4 bytes", body)
		}
	})

	t.Run("no_range_serves_the_whole_file_untouched", func(t *testing.T) {
		resp := get(t, srv, "/media/it_tok/original?token="+token, nil)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		if body := string(readBody(t, resp)); body != original {
			t.Fatalf("body = %q, want the original bytes untransformed", body)
		}
	})

	t.Run("unsatisfiable_range_rejected", func(t *testing.T) {
		resp := get(t, srv, "/media/it_tok/original?token="+token, http.Header{"Range": {"bytes=999-"}})
		if resp.StatusCode != http.StatusRequestedRangeNotSatisfiable {
			t.Fatalf("status = %d, want 416", resp.StatusCode)
		}
	})
}

func mustForeignToken(t *testing.T) string {
	t.Helper()
	other := &Service{Secret: []byte("another-secret entirely"), TokenTTL: time.Hour}
	other.normalize()
	tok, _ := other.Issue("it_tok", timeNow())
	return tok
}

// mustOtherItemToken mints a valid token naming a DIFFERENT item.
func mustOtherItemToken(t *testing.T, s *Service) string {
	t.Helper()
	tok, _ := s.Issue("it_other", timeNow())
	return tok
}

// mustExpiredToken mints a token whose TTL has already passed.
func mustExpiredToken(t *testing.T, s *Service) string {
	t.Helper()
	tok, _ := s.Issue("it_tok", timeNow().Add(-2*s.TokenTTL))
	return tok
}

// readBody drains a response body (the tests' only body read).
func readBody(t *testing.T, resp *http.Response) []byte {
	t.Helper()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read body: %v", err)
	}
	return b
}

// healthyPlaylist is the minimal complete single-variant playlist the
// handwritten builds publish: an init segment, two listed segments, ENDLIST.
const healthyPlaylist = "#EXTM3U\n" +
	"#EXT-X-VERSION:7\n" +
	"#EXT-X-TARGETDURATION:4\n" +
	`#EXT-X-MAP:URI="init.mp4"` + "\n" +
	"#EXTINF:4.0,\nseg-00000.m4s\n" +
	"#EXTINF:4.0,\nseg-00001.m4s\n" +
	"#EXT-X-ENDLIST\n"

// handBuild materializes one minimal handwritten single-variant build under
// root/<itemID>/<nonce>: the playlist bytes at index.m3u8 plus one dummy file
// per named artifact (segments and the init segment — each caller names
// exactly what exists, so a playlist can reference a missing file). Returns
// the build directory. The D5 descriptor guard and ValidateBuild tests judge
// these builds without ever running ffmpeg.
func handBuild(t *testing.T, root, itemID, nonce, playlist string, artifacts ...string) string {
	t.Helper()
	dir := filepath.Join(root, itemID, nonce)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("mkdir build %s: %v", dir, err)
	}
	if err := os.WriteFile(filepath.Join(dir, "index.m3u8"), []byte(playlist), 0o644); err != nil {
		t.Fatalf("write playlist: %v", err)
	}
	for _, a := range artifacts {
		dst := filepath.Join(dir, a)
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			t.Fatalf("mkdir artifact dir %s: %v", a, err)
		}
		if err := os.WriteFile(dst, []byte("artifact-bytes-"+a), 0o644); err != nil {
			t.Fatalf("write artifact %s: %v", a, err)
		}
	}
	return dir
}

// completeDoc is the descriptor input the broken-build tests vary: a stored
// complete build with its artifact pointer and nonce.
func completeDoc(itemID, nonce string) map[string]any {
	return map[string]any{"streams": map[string]any{
		"state":    StateComplete,
		"playlist": mediaPrefix + "/" + itemID + "/" + nonce + "/index.m3u8",
		"nonce":    nonce,
	}}
}

// TestDescribeBrokenBuild is the spec floor for the descriptor's integrity
// guard (D5; probe 076f2d6eece1e791): a complete doc whose on-disk build is
// broken — a referenced segment missing, or a complete playlist omitting
// published segments — answers the direct floor with the original URL, never
// a playlist the player would die on; a healthy handwritten build answers
// hls at the stored playlist URL.
func TestDescribeBrokenBuild(t *testing.T) {
	s := &Service{Secret: []byte("k"), Root: t.TempDir()}

	t.Run("referenced_segment_missing_answers_direct", func(t *testing.T) {
		handBuild(t, s.Root, "it", "n1", healthyPlaylist, "init.mp4", "seg-00000.m4s") // seg-00001 referenced but never written
		mode, state, playURL, _, _ := s.Describe("it", completeDoc("it", "n1"))
		if mode != ModeDirect || state != StateComplete {
			t.Fatalf("mode/state = %q/%q, want %q/%q (broken build takes the floor)", mode, state, ModeDirect, StateComplete)
		}
		if !strings.HasPrefix(playURL, "/media/it/original?token=") {
			t.Fatalf("playURL = %q, want the original URL", playURL)
		}
	})

	t.Run("complete_playlist_omitting_published_segments_answers_direct", func(t *testing.T) {
		handBuild(t, s.Root, "it", "n2",
			"#EXTM3U\n#EXTINF:4.0,\nseg-00000.m4s\n#EXT-X-ENDLIST\n",
			"seg-00000.m4s", "t/seg-00001.m4s") // published under t/, never listed
		mode, state, playURL, _, _ := s.Describe("it", completeDoc("it", "n2"))
		if mode != ModeDirect || state != StateComplete {
			t.Fatalf("mode/state = %q/%q, want %q/%q (stranded segment takes the floor)", mode, state, ModeDirect, StateComplete)
		}
		if !strings.HasPrefix(playURL, "/media/it/original?token=") {
			t.Fatalf("playURL = %q, want the original URL", playURL)
		}
	})

	t.Run("healthy_build_answers_hls", func(t *testing.T) {
		handBuild(t, s.Root, "it", "n3", healthyPlaylist, "init.mp4", "seg-00000.m4s", "seg-00001.m4s")
		mode, state, playURL, _, _ := s.Describe("it", completeDoc("it", "n3"))
		if mode != ModeHls || state != StateComplete {
			t.Fatalf("mode/state = %q/%q, want %q/%q", mode, state, ModeHls, StateComplete)
		}
		if !strings.HasPrefix(playURL, "/media/it/n3/index.m3u8?token=") {
			t.Fatalf("playURL = %q, want the stored playlist URL", playURL)
		}
	})
}

// TestValidateBuild is the unit floor for the integrity check itself (D4's
// mechanism half): playlist-relative resolution over the two published
// layouts, the complete-build coverage half, the partial exemption, and the
// invalid shapes (missing dir, unreadable playlist, escaping ref).
func TestValidateBuild(t *testing.T) {
	s := &Service{Root: t.TempDir()}

	t.Run("missing_build_dir_invalid", func(t *testing.T) {
		if err := s.ValidateBuild("it", "nope"); err == nil {
			t.Fatal("ValidateBuild on a missing build dir = nil, want an error")
		}
	})

	t.Run("healthy_single_variant_build_valid", func(t *testing.T) {
		handBuild(t, s.Root, "it", "ok1", healthyPlaylist, "init.mp4", "seg-00000.m4s", "seg-00001.m4s")
		if err := s.ValidateBuild("it", "ok1"); err != nil {
			t.Fatalf("ValidateBuild(healthy) = %v, want nil", err)
		}
	})

	t.Run("rendition_layout_resolves_through_master_and_variant_dirs", func(t *testing.T) {
		// A rendition build's variant playlists reference their tail segments
		// through ../t/rendK/ — the resolution the D2 fix pinned. The master
		// references the variant playlists.
		dir := handBuild(t, s.Root, "it", "rend0n", "#EXTM3U\n",
			"rend0/init.mp4", "rend0/seg-00000.m4s",
			"t/rend0/init.mp4", "t/rend0/seg-00001.m4s")
		master := "#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=1\nrend0/index.m3u8\n"
		if err := os.WriteFile(filepath.Join(dir, "index.m3u8"), []byte(master), 0o644); err != nil {
			t.Fatalf("write master: %v", err)
		}
		variant := "#EXTM3U\n" +
			`#EXT-X-MAP:URI="init.mp4"` + "\n" +
			"#EXTINF:4.0,\nseg-00000.m4s\n" +
			"#EXT-X-DISCONTINUITY\n" +
			`#EXT-X-MAP:URI="../t/rend0/init.mp4"` + "\n" +
			"#EXTINF:4.0,\n../t/rend0/seg-00001.m4s\n" +
			"#EXT-X-ENDLIST\n"
		if err := os.WriteFile(filepath.Join(dir, "rend0", "index.m3u8"), []byte(variant), 0o644); err != nil {
			t.Fatalf("write variant: %v", err)
		}
		if err := s.ValidateBuild("it", "rend0n"); err != nil {
			t.Fatalf("ValidateBuild(rendition) = %v, want nil", err)
		}
	})

	t.Run("partial_build_exempt_from_coverage", func(t *testing.T) {
		// No ENDLIST: the playlist legitimately lags the disk while growing,
		// so a published-but-unlisted segment is NOT invalid.
		handBuild(t, s.Root, "it", "part1",
			"#EXTM3U\n#EXTINF:4.0,\nseg-00000.m4s\n",
			"seg-00000.m4s", "t/seg-00001.m4s")
		if err := s.ValidateBuild("it", "part1"); err != nil {
			t.Fatalf("ValidateBuild(partial) = %v, want nil (coverage exempt)", err)
		}
	})

	t.Run("partial_build_still_needs_referenced_files", func(t *testing.T) {
		handBuild(t, s.Root, "it", "part2", "#EXTM3U\n#EXTINF:4.0,\nseg-00000.m4s\n") // nothing written
		if err := s.ValidateBuild("it", "part2"); err == nil {
			t.Fatal("ValidateBuild(partial, missing segment) = nil, want an error (reachability holds at every state)")
		}
	})

	t.Run("unreadable_playlist_invalid", func(t *testing.T) {
		dir := handBuild(t, s.Root, "it", "ro1", healthyPlaylist, "init.mp4", "seg-00000.m4s", "seg-00001.m4s")
		if err := os.Chmod(filepath.Join(dir, "index.m3u8"), 0o000); err != nil {
			t.Fatalf("chmod: %v", err)
		}
		t.Cleanup(func() { os.Chmod(filepath.Join(dir, "index.m3u8"), 0o644) })
		if err := s.ValidateBuild("it", "ro1"); err == nil {
			t.Fatal("ValidateBuild(unreadable playlist) = nil, want an error")
		}
	})

	t.Run("ref_escaping_the_build_invalid", func(t *testing.T) {
		// The referenced file EXISTS on disk — just not inside the build. The
		// strict /media join could never serve it, so the ref is invalid.
		handBuild(t, s.Root, "it", "esc1",
			"#EXTM3U\n#EXTINF:4.0,\n../other/seg-00000.m4s\n#EXT-X-ENDLIST\n")
		if err := os.MkdirAll(filepath.Join(s.Root, "other"), 0o755); err != nil {
			t.Fatalf("mkdir other: %v", err)
		}
		if err := os.WriteFile(filepath.Join(s.Root, "other", "seg-00000.m4s"), []byte("x"), 0o644); err != nil {
			t.Fatalf("write outside segment: %v", err)
		}
		if err := s.ValidateBuild("it", "esc1"); err == nil {
			t.Fatal("ValidateBuild(escaping ref) = nil, want an error")
		}
	})
}

// logBuffer is a slog handler that accumulates every record's message, so a
// test can assert nothing sensitive was ever logged.
type logBuffer struct {
	mu  sync.Mutex
	buf bytes.Buffer
}

func (h *logBuffer) Enabled(context.Context, slog.Level) bool { return true }
func (h *logBuffer) Handle(_ context.Context, r slog.Record) error {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.buf.WriteString(r.Message)
	h.buf.WriteByte('\n')
	return nil
}
func (h *logBuffer) WithAttrs([]slog.Attr) slog.Handler { return h }
func (h *logBuffer) WithGroup(string) slog.Handler      { return h }
func (h *logBuffer) String() string {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.buf.String()
}
